var t=[{title:`Leer de beweging`,text:`Sta met soepele knieën. Duw je heupen naar achteren alsof je er een autodeur mee dichtdoet, en laat je romp naar voren kantelen terwijl je rug in een comfortabele, beheerste positie blijft. Stop als je hamstrings de beweging beperken of je romp niet meer beheerst kan blijven, en duw dan je heupen naar voren om op te staan. Je traint heupbeweging, dus de vloer aanraken is niet het doel.`},{title:`Heupscharnier en squat`,text:`Beide bewegingen gebruiken de heupen en knieën, met een andere nadruk. Bij een squat buigen de knieën meestal meer en blijft de romp meer rechtop. Bij een Roemeense deadlift buigen de knieën een beetje en gaan de heupen verder naar achteren, wat meer werk op de achterkant van het lichaam legt. Een glute bridge traint heupstrekking met een ondersteunde romp en is soms een makkelijkere plek om te beginnen.`},{title:`Oefeningen om het te leren`,text:`Ga voor een wall tap een kleine stap van een muur af staan en duw je heupen naar achteren tot ze de muur raken. Een lichte stok langs je hoofd, bovenrug en bekken kan je laten merken wanneer je wervelkolom veel beweegt. Gebruik deze oefeningen om te leren en forceer er geen stijve houding door.`},{title:`Opbouw en fouten`,text:`Begin met herhalingen zonder gewicht en ga dan naar een lichte kettlebelldeadlift of een Roemeense deadlift met dumbbells. Houd het gewicht dichtbij en gebruik een bereik dat je kunt beheersen. Je knieën te veel buigen maakt van de oefening een squat, en een vaste diepte najagen kan de beweging naar je rug verplaatsen. Swings vragen meer vaardigheid dan een langzaam heupscharnier.`},{title:`TrainUp gebruiken`,text:`Je schema bevat heupscharnieroefeningen die passen bij je uitrusting en doel. Als balans of een gevoelige rug beladen heupscharnieren moeilijk maakt, is een ondersteunde variant of een heupbrug een optie, en je kunt een rugbeperking noteren in Profiel. Houdt de pijn aan, ga dan naar een arts of fysiotherapeut in plaats van zelf een revalidatieplan te maken.`}];var a=[{label:`ACE-oefeningenbibliotheek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`ACE: techniek van de tweehandige kettlebellswing`,url:`https://www.acefitness.org/continuing-education/certified/january-2025/8788/the-ace-do-it-better-series-the-two-handed-kettlebell-swing/`},{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`}];var i={sections:t,sources:a};export{i as default,t as sections,a as sources};